(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-114":{scenario:{company:"Coral Peak Plastics",supervisor:{name:"Đỗ Minh Quân",role:{vi:"Kế toán trưởng nhà máy",en:"Plant Chief Accountant"}},ref_code:"CP-2610",title:{vi:"Giá thành thật, tồn kho thật, lợi nhuận thật.",en:"True cost, true inventory, true profit."},brief:{vi:"Bạn soát phiếu tính giá thành CP-2610 tháng 10/2026 của dây chuyền ép nhựa. Công suất bình thường 10.000 sản phẩm/tháng, thực tế sản xuất 8.000 sản phẩm, không có dở dang đầu và cuối kỳ. Chi phí (số liệu mô phỏng): nguyên vật liệu trực tiếp 1.200 triệu đồng, nhân công trực tiếp 480 triệu đồng, sản xuất chung biến đổi 160 triệu đồng, sản xuất chung cố định 400 triệu đồng. Sửa tài khoản ghi nhận phần chi phí cố định không phân bổ và giá thành đơn vị theo VAS 02.",en:"You are reviewing cost sheet CP-2610 for October 2026 of the injection molding line. Normal capacity is 10,000 units per month, actual output is 8,000 units, with no opening or closing work in progress. Costs (training data): direct materials VND 1,200 million, direct labor VND 480 million, variable overhead VND 160 million, fixed overhead VND 400 million. Correct the account for unallocated fixed overhead and the unit cost under VAS 02."},reference_title:{vi:"Chính sách giá thành & bảng phân bổ đã duyệt · CP-2610",en:"Approved costing policy & allocation sheet · CP-2610"},fields:[{id:"UNALLOC_ACC",label:{vi:"TK ghi nhận chi phí SXC cố định không phân bổ",en:"Account for unallocated fixed overhead"},initial:"154",expected:"632",choices:["154","632","642"],reference:"Chính sách giá thành - VAS 02",hint:{vi:"Phần chi phí cố định ứng với công suất không sử dụng không được treo vào giá trị tồn kho, mà là chi phí sản xuất kinh doanh của kỳ.",en:"Fixed cost tied to idle capacity must not sit in inventory value; it is a production cost of the period."}},{id:"UNIT_COST",label:{vi:"Giá thành đơn vị (VND/sản phẩm)",en:"Unit cost (VND per unit)"},initial:"280000",expected:"270000",reference:"Bảng phân bổ chi phí sản xuất chung",ref_value:{vi:"Công suất bình thường 10.000 sp; thực tế 8.000 sp; SXC cố định 400 triệu đồng; chi phí biến đổi 1.840 triệu đồng",en:"Normal capacity 10,000 units; actual 8,000 units; fixed overhead VND 400 million; variable costs VND 1,840 million"},hint:{vi:"Chỉ phân bổ chi phí cố định theo tỷ lệ sản lượng thực tế trên công suất bình thường khi sản lượng thấp hơn công suất.",en:"Allocate fixed overhead by actual output over normal capacity when output is below capacity."}}],sop32:{vi:"SXC cố định phân bổ = SXC cố định x sản lượng thực tế / công suất bình thường (khi thực tế thấp hơn); giá thành đơn vị = (NVLTT + NCTT + SXC biến đổi + SXC cố định phân bổ) / sản lượng hoàn thành.",en:"Allocated fixed overhead = fixed overhead x actual output / normal capacity (when output is lower); unit cost = (DM + DL + variable overhead + allocated fixed overhead) / units completed."},context:{label:"PHIẾU GIÁ THÀNH NHÁP / CP-2610",metrics:[{label:{vi:"Công suất bình thường",en:"Normal capacity"},value:"10,000"},{label:{vi:"Sản lượng thực tế",en:"Actual output"},value:"8,000"},{label:{vi:"SXC cố định",en:"Fixed overhead"},value:"400,000,000 VND"}]},crisis:{vi:"Giám đốc nhà máy đề nghị: “Đưa hết 400 triệu chi phí cố định vào giá thành nhập kho cho giá vốn tháng này thấp, lợi nhuận đạt KPI để cả xưởng được thưởng. Không thì sửa công suất bình thường xuống 8.000 cho khớp.”",en:"The plant director asks: “Put the whole 400 million of fixed cost into inventory so this month's cost of sales is low and we hit the KPI bonus. Otherwise just change normal capacity to 8,000.”"},options:{safe:{vi:"Giữ phương pháp theo VAS 02, ghi phần cố định không phân bổ vào giá vốn, báo kế toán trưởng; nếu cần xem lại công suất bình thường thì đề xuất đánh giá kỹ thuật có căn cứ và phê duyệt chính thức.",en:"Keep the VAS 02 method, book unallocated fixed cost to cost of sales and inform the chief accountant; propose a documented technical review if normal capacity needs revisiting."},shortcut:{vi:"Vốn hóa toàn bộ chi phí cố định vào tồn kho cho đạt KPI, cuối năm tính lại sau.",en:"Capitalize all fixed cost into inventory to hit the KPI and recalculate at year end."},wait:{vi:"Tạm dừng khóa sổ giá thành và chờ giám đốc nhà máy tự quyết định phương pháp.",en:"Pause the cost close and wait for the plant director to choose the method."}},questions:{vi:["Vì sao phần chi phí SXC cố định không phân bổ ghi vào TK 632 mà không vào TK 154? Trình bày cách bạn tính lại giá thành đơn vị.","Nếu vốn hóa toàn bộ chi phí cố định vào tồn kho, báo cáo tài chính bị sai lệch thế nào và ai phải được báo cáo?"],en:["Why is unallocated fixed overhead booked to account 632 rather than 154? Show how you recalculated the unit cost.","If all fixed cost were capitalized into inventory, how would the financial statements be misstated and who must be informed?"]},hints:{vi:["Đặt phiếu giá thành nháp cạnh chính sách giá thành và so sản lượng thực tế với công suất bình thường.","Tách phần chi phí cố định được phân bổ và phần không phân bổ trước khi chia cho sản lượng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không thay đổi phương pháp hay thông số giá thành để đạt chỉ tiêu thưởng."],en:["Place the draft cost sheet next to the costing policy and compare actual output with normal capacity.","Split allocated and unallocated fixed cost before dividing by output in SOP 3.2.","Re-read SOP 4.2: never change costing methods or parameters to hit bonus targets."]}},learning:{summary:{vi:"Kế toán giá thành tập hợp và phân bổ chi phí nguyên vật liệu, nhân công, sản xuất chung cho từng sản phẩm, đơn hàng hoặc công đoạn, đánh giá sản phẩm dở dang, tính giá thành và phân tích biến động so với định mức. Thông tin giá thành giúp định giá bán, kiểm soát lãng phí và ghi nhận đúng giá trị tồn kho, giá vốn. Nghề đòi hỏi hiểu quy trình sản xuất, nắm VAS 02 và phối hợp chặt với kho, kỹ thuật, kế hoạch.",en:"A cost accountant collects and allocates materials, labor and overhead to products, orders or process stages, values work in progress, computes product cost and analyzes variances against standards. Cost data supports pricing, waste control and correct inventory and cost of sales. The role requires understanding the production process, command of VAS 02 and close work with the warehouse, engineering and planning teams."},responsibilities:{vi:["Tập hợp chi phí NVL trực tiếp, nhân công trực tiếp và sản xuất chung theo đối tượng tính giá thành.","Phân bổ chi phí sản xuất chung theo tiêu thức đã duyệt và công suất bình thường.","Đánh giá sản phẩm dở dang cuối kỳ và tính giá thành thành phẩm.","Phân tích biến động giá, lượng so với định mức và báo cáo nguyên nhân.","Phối hợp kiểm kê, đối chiếu định mức tiêu hao và đề xuất cập nhật định mức."],en:["Collect direct materials, direct labor and overhead by costing object.","Allocate overhead using approved drivers and normal capacity.","Value closing work in progress and compute finished goods cost.","Analyze price and usage variances against standards and report causes.","Support stock counts, compare consumption standards and propose updates."]},competencies:[{name:{vi:"Phương pháp tính giá thành",en:"Costing methods"},desc:{vi:"Áp dụng phương pháp giản đơn, hệ số, tỷ lệ, phân bước hoặc theo đơn đặt hàng phù hợp quy trình.",en:"Apply simple, coefficient, ratio, process or job costing to fit the production flow."}},{name:{vi:"Phân bổ chi phí chung",en:"Overhead allocation"},desc:{vi:"Chọn tiêu thức phân bổ hợp lý và xử lý chi phí cố định khi sản lượng dưới công suất.",en:"Choose sound allocation drivers and handle fixed cost when output is below capacity."}},{name:{vi:"Phân tích biến động",en:"Variance analysis"},desc:{vi:"Tách biến động giá, lượng, hiệu suất và giải thích bằng dữ liệu sản xuất.",en:"Split price, usage and efficiency variances and explain them with production data."}},{name:{vi:"Hiểu quy trình sản xuất",en:"Process understanding"},desc:{vi:"Đọc lệnh sản xuất, định mức BOM, báo cáo sản lượng và phế phẩm tại xưởng.",en:"Read work orders, BOM standards, output and scrap reports on the shop floor."}},{name:{vi:"Chính trực số liệu",en:"Data integrity"},desc:{vi:"Không điều chỉnh thông số giá thành để làm đẹp lợi nhuận hay đạt chỉ tiêu thưởng.",en:"Never tweak costing parameters to dress up profit or hit bonus targets."}}],knowledge:{vi:["VAS 02 Hàng tồn kho: giá gốc gồm chi phí mua, chi phí chế biến và chi phí liên quan trực tiếp khác.","Nguyên tắc phân bổ chi phí sản xuất chung cố định theo công suất bình thường; phần không phân bổ ghi vào chi phí trong kỳ.","Hệ thống TK 621, 622, 627, 154, 155, 632 theo chế độ kế toán doanh nghiệp (Thông tư 200/2014/TT-BTC và văn bản thay thế).","Thông tư 53/2006/TT-BTC hướng dẫn áp dụng kế toán quản trị trong doanh nghiệp.","Chi phí định mức, giá thành kế hoạch và phương pháp chi phí theo hoạt động (ABC)."],en:["VAS 02 Inventories: cost includes purchase, conversion and other directly attributable costs.","Fixed production overhead is allocated on normal capacity; the unallocated part is expensed in the period.","Accounts 621, 622, 627, 154, 155 and 632 under the enterprise accounting regime (Circular 200/2014/TT-BTC and its replacement).","Circular 53/2006/TT-BTC guiding management accounting in enterprises.","Standard costing, budgeted cost and activity-based costing (ABC)."]},tools:["Phần mềm ERP phân hệ giá thành","Hệ thống quản lý sản xuất (MES)","Microsoft Excel","Bảng định mức nguyên vật liệu (BOM)","Công cụ BI phân tích chi phí"],kpis:{vi:["Số ngày hoàn tất tính giá thành sau khi khóa sổ kho.","Mức chênh lệch giữa giá thành thực tế và định mức theo từng mã sản phẩm.","Tỷ lệ điều chỉnh giá trị tồn kho do kiểm toán (mục tiêu bằng 0).","Số đề xuất tiết kiệm chi phí được triển khai mỗi quý."],en:["Days to finish costing after the inventory close.","Gap between actual and standard cost per product code.","Audit adjustments to inventory value (target zero).","Cost-saving proposals implemented per quarter."]},day:[{time:"08:00",vi:"Nhận báo cáo sản lượng, phế phẩm ca đêm và đối chiếu với phiếu xuất nguyên vật liệu.",en:"Receive night-shift output and scrap reports and match them with material issues."},{time:"10:00",vi:"Phân bổ chi phí điện, khấu hao, bảo trì vào các dây chuyền theo tiêu thức đã duyệt.",en:"Allocate power, depreciation and maintenance to lines using approved drivers."},{time:"13:30",vi:"Phân tích biến động tiêu hao hạt nhựa so với định mức cùng trưởng ca sản xuất.",en:"Analyze resin usage variance against standard with the shift leader."},{time:"15:30",vi:"Đánh giá sản phẩm dở dang, lập phiếu tính giá thành và bút toán kết chuyển.",en:"Value work in progress, prepare the cost sheet and closing entries."},{time:"17:00",vi:"Gửi báo cáo giá thành và đề xuất cập nhật định mức cho kế toán trưởng.",en:"Send the cost report and standard update proposals to the chief accountant."}],mistakes:{vi:["Vốn hóa toàn bộ chi phí cố định vào tồn kho khi sản lượng thấp, làm giá thành và tồn kho bị thổi phồng.","Dùng tiêu thức phân bổ không phản ánh mức sử dụng nguồn lực, khiến giá thành từng sản phẩm méo mó.","Bỏ qua sản phẩm dở dang cuối kỳ, đẩy toàn bộ chi phí vào thành phẩm."],en:["Capitalizing all fixed cost into inventory when output is low, inflating unit cost and stock.","Using allocation drivers that do not reflect resource use, distorting product costs.","Ignoring closing work in progress and pushing all costs into finished goods."]},career:[{vi:"Nhân viên kế toán kho - sản xuất",en:"Inventory & production accounting clerk"},{vi:"Kế toán giá thành",en:"Cost accountant"},{vi:"Trưởng nhóm kế toán quản trị chi phí",en:"Cost & management accounting lead"},{vi:"Kiểm soát viên tài chính nhà máy (Plant Controller)",en:"Plant Controller"}],glossary:[{term:"Công suất bình thường",vi:"Sản lượng đạt được trung bình trong điều kiện sản xuất bình thường, dùng làm căn cứ phân bổ chi phí cố định.",en:"Normal capacity: the average output under normal conditions, used to allocate fixed overhead."},{term:"WIP",vi:"Sản phẩm dở dang: sản phẩm đang trong quá trình chế biến, chưa hoàn thành tại cuối kỳ.",en:"Work in progress: products still being processed and not finished at period end."},{term:"BOM",vi:"Định mức nguyên vật liệu: danh sách và số lượng vật tư cần cho một đơn vị sản phẩm.",en:"Bill of materials: the list and quantities of materials needed per unit of product."},{term:"Standard cost",vi:"Giá thành định mức xây dựng trước, dùng để so sánh và phân tích biến động với thực tế.",en:"A predetermined cost used to compare with and analyze variances from actual cost."},{term:"ABC",vi:"Phương pháp chi phí theo hoạt động: phân bổ chi phí chung theo các hoạt động tiêu dùng nguồn lực.",en:"Activity-based costing: allocating overhead through the activities that consume resources."}],quiz:[{q:{vi:"Công suất bình thường 5.000 sp, thực tế 4.000 sp, SXC cố định 100 triệu đồng. Phần SXC cố định ghi vào giá vốn trong kỳ là bao nhiêu?",en:"Normal capacity is 5,000 units, actual output 4,000 units, fixed overhead VND 100 million. How much fixed overhead goes to cost of sales in the period?"},options:{vi:["0 đồng","20 triệu đồng","80 triệu đồng","100 triệu đồng"],en:["VND 0","VND 20 million","VND 80 million","VND 100 million"]},answer:1,explain:{vi:"Phân bổ vào giá thành 100 x 4.000 / 5.000 = 80 triệu đồng; 20 triệu đồng không phân bổ ghi vào giá vốn.",en:"Allocated to product 100 x 4,000 / 5,000 = VND 80 million; the unallocated VND 20 million goes to cost of sales."}},{q:{vi:"Khoản nào KHÔNG được tính vào giá gốc hàng tồn kho theo VAS 02?",en:"Which item is NOT included in inventory cost under VAS 02?"},options:{vi:["Chi phí nguyên vật liệu trực tiếp","Chi phí nhân công trực tiếp","Chi phí sản xuất chung biến đổi","Chi phí bán hàng"],en:["Direct materials","Direct labor","Variable production overhead","Selling expenses"]},answer:3,explain:{vi:"Chi phí bán hàng, chi phí quản lý doanh nghiệp và hao hụt bất thường không tính vào giá gốc hàng tồn kho.",en:"Selling costs, administrative costs and abnormal waste are excluded from inventory cost."}},{q:{vi:"Phương pháp tính giá thành nào phù hợp nhất cho xưởng in sản xuất theo từng đơn hàng riêng biệt?",en:"Which costing method best suits a print shop producing separate customer orders?"},options:{vi:["Theo đơn đặt hàng","Phân bước","Hệ số","Giản đơn một sản phẩm"],en:["Job order costing","Process costing","Coefficient method","Simple single-product method"]},answer:0,explain:{vi:"Sản xuất theo đơn hàng riêng biệt tập hợp chi phí và tính giá thành cho từng đơn đặt hàng.",en:"Separate orders call for collecting and computing cost per job."}},{q:{vi:"Giám đốc nhà máy yêu cầu hạ công suất bình thường xuống bằng sản lượng thực tế để giá vốn tháng này thấp. Bạn làm gì?",en:"The plant director asks you to set normal capacity equal to actual output to lower this month's cost of sales. What do you do?"},options:{vi:["Làm theo vì giám đốc hiểu sản xuất nhất","Sửa trong tháng này rồi trả lại tháng sau","Từ chối, giữ thông số đã duyệt và báo kế toán trưởng; chỉ thay đổi khi có đánh giá kỹ thuật được phê duyệt","Bỏ qua chi phí cố định trong tháng"],en:["Comply since the director knows production best","Change it this month and revert next month","Refuse, keep the approved parameter and inform the chief accountant; change only after an approved technical review","Leave out fixed cost for the month"]},answer:2,explain:{vi:"Thay đổi thông số để đạt chỉ tiêu là làm sai lệch báo cáo; mọi thay đổi phải có căn cứ kỹ thuật và phê duyệt.",en:"Changing parameters to hit targets misstates the accounts; changes need technical evidence and approval."}}],tools_en:["ERP product costing module","Manufacturing execution system (MES)","Microsoft Excel","Bill of materials (BOM)","BI tool for cost analysis"]}}})})(window.KKR);
